package br.masmangan.beecrowd.bee1002;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.*;

public class CircleGetAreaTest {

	private Circle circle;

	@BeforeEach
	public void setUp() {
		circle = new Circle();
	}

	@Test
	@Tag("valid")
	public void calculateAreaWithPositiveRadius() {
		circle.setRadius(5.0);
		double area = circle.getArea();
		assertEquals(Math.PI * 5.0 * 5.0, area, 0.0001);
	}

	@Test
	@Tag("boundary")
	public void calculateAreaWithZeroRadius() {
		circle.setRadius(0.0);
		double area = circle.getArea();
		assertEquals(0.0, area, 0.0001);
	}

	@Test
	@Tag("invalid")
	public void calculateAreaWithNegativeRadius() {
		circle.setRadius(-5.0);
		double area = circle.getArea();
		assertEquals(0.0, area, 0.0001);
	}

	@Test
	@Tag("boundary")
	public void calculateAreaWithMaxDoubleValue() {
		circle.setRadius(Double.MAX_VALUE);
		double area = circle.getArea();
		assertTrue(Double.isInfinite(area));
	}

	@Test
	@Tag("boundary")
	public void calculateAreaWithMinDoubleValue() {
		circle.setRadius(Double.MIN_VALUE);
		double area = circle.getArea();
		assertTrue(Double.isFinite(area));
	}

	@Test
	@Tag("invalid")
	public void calculateAreaWithNaNRadius() {
		circle.setRadius(Double.NaN);
		double area = circle.getArea();
		assertTrue(Double.isNaN(area));
	}

	@Test
	@Tag("invalid")
	public void calculateAreaWithInfinityRadius() {
		circle.setRadius(Double.POSITIVE_INFINITY);
		double area = circle.getArea();
		assertTrue(Double.isInfinite(area));
	}

	@Test
	@Tag("invalid")
	public void calculateAreaWithNegativeInfinityRadius() {
		circle.setRadius(Double.NEGATIVE_INFINITY);
		double area = circle.getArea();
		assertTrue(Double.isNaN(area));
	}

}
